SELECT 
FROM product


        AND product_name LIKE CONCAT('%', #{productName}, '%')


        AND category = #{category}


        AND brand = #{brand}


        AND status = #{status}


        AND unit_price >= #{minPrice}


        AND unit_price <= #{maxPrice}


ORDER BY product_id

