UPDATE product
product_code = #{productCode}, product_name = #{productName}, category = #{category}, brand = #{brand}, unit = #{unit}, unit_price = #{unitPrice}, stock_quantity = #{stockQuantity}, min_stock = #{minStock}, status = #{status}, production_date = #{productionDate}, description = #{description},
WHERE product_id = #{productId}
